"use strict";

const prettier = require("prettier-local");
const runPrettier = require("../runPrettier.js");

test("allows custom parser provided as object", () => {
  const output = prettier.format("1", {
    parser(text) {
      expect(text).toBe("1");
      return {
        type: "Literal",
        value: 2,
        raw: "2",
      };
    },
  });
  expect(output).toBe("2");
});

test("allows usage of prettier's supported parsers", () => {
  const output = prettier.format("foo ( )", {
    parser(text, parsers) {
      expect(typeof parsers.babel).toBe("function");
      const ast = parsers.babel(text);
      ast.program.body[0].expression.callee.name = "bar";
      return ast;
    },
  });
  expect(output).toBe("bar();\n");
});

test("allows add empty `trailingComments` array", () => {
  const output = prettier.format("(foo /* comment */)( )", {
    parser(text, parsers) {
      const ast = parsers.babel(text);

      // This may happens in this use case https://github.com/prettier/prettier/pull/5497#issuecomment-439841965
      // Simply simulate it
      const callExpression = ast.program.body[0].expression;
      callExpression.extra = { parenthesized: true };
      callExpression.trailingComments = [];

      return ast;
    },
  });
  expect(output).toBe("foo(/* comment */);\n");
});

describe("allows passing a string to resolve a parser", () => {
  runPrettier("./custom-parsers/", [
    "--end-of-line",
    "lf",
    "./custom-rename-input.js",
    "--parser",
    "./custom-rename-parser",
  ]).test({
    status: 0,
  });
});
"use strict";

const {
  __debug: { parse, formatAST, formatDoc, printToDoc, printDocToString },
  doc: {
    builders,
    utils: { cleanDoc },
  },
} = require("prettier-local");
const { outdent } = require("outdent");

const code = outdent`
  const foo =              'bar'
`;
const formatted = 'const foo = "bar";\n';
const options = { parser: "babel", originalText: code };

describe("API", () => {
  const { ast } = parse(code, options);
  test("prettier.parse", () => {
    expect(Array.isArray(ast.program.body)).toBe(true);
  });

  const { formatted: formatResultFromAST } = formatAST(ast, options);
  test("prettier.formatAST", () => {
    expect(formatResultFromAST).toBe(formatted);
  });

  const doc = printToDoc(code, options);
  test("prettier.printToDoc", (done) => {
    // If it's array, it's a `concat`
    if (!Array.isArray(doc)) {
      expect(doc.type).toBe("concat");
      expect(Array.isArray(doc.parts)).toBe(true);
    }
    done();
  });

  const formatResultFromDoc = formatDoc(doc, options);
  test("prettier.formatDoc", () => {
    expect(formatResultFromDoc).toMatchSnapshot();
  });

  const { formatted: stringFromDoc } = printDocToString(doc, options);
  test("prettier.printDocToString", () => {
    expect(stringFromDoc).toBe(formatted);
  });

  const doc2 = new Function(
    `{ ${Object.keys(builders)} }`,
    `return ${formatResultFromDoc}`
  )(builders);
  const { formatted: stringFromDoc2 } = printDocToString(doc2, options);
  const formatResultFromDoc2 = formatDoc(doc2, options);
  test("output of prettier.formatDoc can be reused as code", () => {
    expect(stringFromDoc2).toBe(formatted);
    expect(formatResultFromDoc2).toBe(formatResultFromDoc);
  });

  test("prettier.formatDoc prints things as expected", () => {
    const {
      indent,
      hardline,
      literalline,
      fill,
      ifBreak,
      indentIfBreak,
      group,
      line,
      label,
    } = builders;

    expect(formatDoc([indent(hardline), indent(literalline)])).toBe(
      "[indent(hardline), indent(literalline)]"
    );

    expect(formatDoc(fill(["foo", hardline, "bar", literalline, "baz"]))).toBe(
      'fill(["foo", hardline, "bar", literalline, "baz"])'
    );

    expect(
      formatDoc(
        // The argument of fill must not be passed to cleanDoc because it's not a doc
        fill(cleanDoc(["foo", literalline, "bar"])) // invalid fill
      )
    ).toBe('fill(["foo", literallineWithoutBreakParent, breakParent, "bar"])');

    expect(
      formatDoc(indentIfBreak(group(["1", line, "2"]), { groupId: "Q" }))
    ).toBe('indentIfBreak(group(["1", line, "2"]), { groupId: "Q" })');

    expect(formatDoc(label("foo", group(["1", line, "2"])))).toBe(
      'label("foo", group(["1", line, "2"]))'
    );

    expect(formatDoc([ifBreak("a", "b"), ifBreak("a"), ifBreak("", "b")])).toBe(
      '[ifBreak("a", "b"), ifBreak("a"), ifBreak("", "b")]'
    );
  });
});
// Public verification helper: its defaults come only from the original checkout.
const fs=require('fs'),path=require('path'),{spawnSync}=require('child_process');
const root=process.cwd(),config=JSON.parse(fs.readFileSync('verification.json','utf8')),args=process.argv.slice(2);
const value=name=>{const index=args.indexOf(name);return index<0?undefined:args[index+1];};
const report=path.resolve(value('--report')||'.v4-tmp/public-report.json');fs.mkdirSync(path.dirname(report),{recursive:true});
const selected=value('--tests-json'),tests=selected?JSON.parse(fs.readFileSync(selected,'utf8')):config.publicTests;
const env={...process.env,CI:'true',TZ:'UTC',NODE_ENV:'test',NODE_OPTIONS:'--max-old-space-size=384',SUFFICE_EVAL_REPORT:report};
const execute=(argv,timeout=240000)=>spawnSync(config.nodeRuntime,['--max-old-space-size=384',...argv],{cwd:root,env,encoding:'utf8',windowsHide:true,timeout,maxBuffer:16*1024**2});
for(const build of config.buildSteps){
  const result=execute(build,120000);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
  if(result.status!==0){fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'build',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));process.exit(result.status||1);}
}
let invocation;
if(config.framework==='mocha')invocation=['node_modules/mocha/bin/_mocha',...(config.mochaRequires??[]).flatMap(name=>['--require',name]),...tests,'--reporter',path.resolve('.v4-mocha-reporter.cjs'),'--timeout','15000','--exit'];
else if(config.framework==='jest')invocation=['node_modules/jest/bin/jest.js','--runInBand','--watchman=false','--json','--outputFile',report,'--no-cache','--runTestsByPath',...tests];
else if(config.framework==='qunit')invocation=['.v4-qunit-runner.cjs',config.qunitEntry];
else throw new Error('Unknown verified framework');
const result=execute(invocation);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
if(!fs.existsSync(report))fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'test',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));
if(result.error)process.stderr.write('\n'+result.error.message+'\n');
console.log('\nVerification report: '+path.relative(root,report));process.exit(result.status??1);

